};

// ---------------- PDF UPLOAD ----------------
const handleFileUpload = async (e) => {
const file = e.target.files[0];
if (!file) return;


setMessages((prev) => [
  ...prev,
  { sender: "user", text: `📄 Uploaded: ${file.name}` }
]);

try {
  await uploadPDF(file);

  setMessages((prev) => [
    ...prev,
    {
      sender: "bot",
      text: "✅ PDF uploaded successfully! Now ask questions from it."
    }
  ]);

} catch (err) {
  console.error(err);

  setMessages((prev) => [
    ...prev,
    { sender: "bot", text: "❌ PDF upload failed" }
  ]);
}


};

return ( <div className="container">


  {/* 🔥 Toggle Button */}
  <button
    onClick={() => setIsAdmin(!isAdmin)}
    style={{
      marginBottom: "10px",
      padding: "8px 12px",
      cursor: "pointer"
    }}
  >
    {isAdmin
      ? "👨‍🎓 Switch to User Panel"
      : "👨‍🏫 Switch to Admin Panel"}
  </button>

  {/* ---------------- ADMIN PANEL ---------------- */}
  {isAdmin ? (
    <AdminDashboard />
  ) : (
    <>
      <h2>EduSaarthi</h2>
      <p>Multilingual University Helpdesk</p>

      {/* PDF Upload */}
      <input
        type="file"
        accept="application/pdf"
        onChange={handleFileUpload}
        style={{ marginBottom: "10px" }}
      />

      <ChatWindow messages={messages} />
      <ChatInput onSend={handleSend} />
    </>
  )}
</div>


);
}

export default App;
